def _csharpName(name):
    if name is None:
        return None
    if name.endswith("_") and keyword.iskeyword(name[:-1]):
        return name[:-1]
    return name

def _enumName(enumType, value: int):
    """C# Enum.GetName: the first member with this value, else None."""
    value = int(value)
    names = getattr(enumType, "Names", None)
    if isinstance(names, dict):
        return _csharpName(names.get(value))
    for memberName, member in getattr(enumType, "__members__", {}).items():
        if int(member) == value:
            return _csharpName(memberName)
    return None

def _unixSecondsToInvariant(value: int) -> str:
    """DateTimeOffset.FromUnixTimeSeconds(value).DateTime.ToString(InvariantCulture)."""
    dt = datetime(1970, 1, 1, tzinfo=timezone.utc) + timedelta(seconds=int(value))
    return dt.strftime("%m/%d/%Y %H:%M:%S")

def _propertyDataId_getValueEnumName(self, value: int):
    match self:
        case PropertyDataId.ActivationAnimation | PropertyDataId.InitMotion | PropertyDataId.UseTargetAnimation | PropertyDataId.UseTargetFailureAnimation | PropertyDataId.UseTargetSuccessAnimation | PropertyDataId.UseUserAnimation:
            return _enumName(_enums.MotionCommand, value)
        case PropertyDataId.PhysicsScript | PropertyDataId.RestrictionEffect:
            return _enumName(_enums.PlayScript, value)
        case PropertyDataId.ActivationSound | PropertyDataId.UseSound:
            return _enumName(_enums.Sound, value)
        case PropertyDataId.WieldedTreasureType | PropertyDataId.DeathTreasureType:
            return None
        case PropertyDataId.Spell | PropertyDataId.DeathSpell | PropertyDataId.ProcSpell | PropertyDataId.RedSurgeSpell | PropertyDataId.BlueSurgeSpell | PropertyDataId.YellowSurgeSpell:
            return _enumName(_enums.SpellId, value)
        case PropertyDataId.ItemSkillLimit | PropertyDataId.ItemSpecializedOnly:
            return _enumName(_enums.Skill, value)
        case PropertyDataId.PCAPRecordedParentLocation:
            return _enumName(_enums.ParentLocation, value)
        case PropertyDataId.PCAPRecordedDefaultScript:
            return _enumName(_enums.MotionCommand, value)
        case _:
            return None

