def getDescription(prop) -> str:
    """C# GetDescription: DescriptionAttribute, otherwise the member name."""
    try:
        value = int(prop)
    except (TypeError, ValueError):
        return str(prop)
    text = _DESCRIPTIONS.get((type(prop), value))
    if text is not None:
        return text
    for memberName, member in getattr(type(prop), "__members__", {}).items():
        if int(member) == value:
            return _csharpName(memberName)
    return str(value)

